/**
 * 联系方式/客服页面逻辑
 * type=my: 查看/编辑用户联系方式
 * type=service: 展示客服联系方式
 */

var app = getApp()

Page({
  data: {
    pageType: 'service',
    phone: '',
    wechat: '',
    saving: false
  },

  onLoad: function (options) {
    var type = options.type || 'service'
    this.setData({ pageType: type })

    if (type === 'my') {
      // 读取用户已有联系方式
      var userInfo = app.globalData.userInfo
      if (userInfo) {
        this.setData({
          phone: userInfo.phone || '',
          wechat: userInfo.wechat || ''
        })
      }
      wx.setNavigationBarTitle({ title: '我的联系方式' })
    } else {
      wx.setNavigationBarTitle({ title: '联系客服' })
    }
  },

  onPhoneInput: function (e) {
    this.setData({ phone: e.detail.value })
  },

  onWechatInput: function (e) {
    this.setData({ wechat: e.detail.value })
  },

  /**
   * 保存联系方式
   */
  onSave: function () {
    var that = this
    if (that.data.saving) return

    var phone = (that.data.phone || '').trim()
    var wechat = (that.data.wechat || '').trim()

    if (!phone && !wechat) {
      wx.showToast({ title: '请至少填写一种联系方式', icon: 'none' })
      return
    }

    if (phone && !/^\d{11}$/.test(phone)) {
      wx.showToast({ title: '手机号格式不正确', icon: 'none' })
      return
    }

    that.setData({ saving: true })

    // 调用云函数更新用户信息
    wx.cloud.callFunction({
      name: 'login',
      data: {
        phone: phone,
        wechat: wechat
      },
      success: function (res) {
        var result = res.result
        if (result.code === 0) {
          // 更新本地缓存
          if (app.globalData.userInfo) {
            app.globalData.userInfo.phone = phone
            app.globalData.userInfo.wechat = wechat
            wx.setStorageSync('userInfo', JSON.stringify(app.globalData.userInfo))
          }
          wx.showToast({ title: '保存成功', icon: 'success' })
          setTimeout(function () {
            wx.navigateBack()
          }, 1500)
        } else {
          wx.showToast({ title: result.msg || '保存失败', icon: 'none' })
          that.setData({ saving: false })
        }
      },
      fail: function () {
        wx.showToast({ title: '保存失败，请重试', icon: 'none' })
        that.setData({ saving: false })
      }
    })
  },

  /**
   * 复制客服微信号
   */
  copyWechat: function () {
    wx.setClipboardData({
      data: 'banshuibang-kefu',
      success: function () {
        wx.showToast({ title: '已复制微信号', icon: 'success' })
      }
    })
  },

  /**
   * 拨打客服电话
   */
  callService: function () {
    wx.makePhoneCall({
      phoneNumber: '4008880000'
    })
  }
})
